-- Fakt kartochkalarining ruscha matni — 24-partiya:
-- Dilshod otin, Komil Xorazmiy, Zavqiy, Avaz O'tar, Tavallo, Elbek,
-- Hamid Olimjon, Usmon Nosir.

-- ===== Dilshod otin =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родилась Дилшоди Барно?', fact_ru = 'Я родилась в 1800 году в городе Ура-Тюбе. Мой отец — Рахимкул-суфи, грамоте я выучилась у отца.' WHERE id = 2155;
UPDATE fact_cards SET topic_ru = 'Моё имя и мои псевдонимы', question_ru = 'Каковы настоящее имя и псевдонимы Дилшод-отин?', fact_ru = 'Моё полное имя — Дилшод, дочь Рахимкула-суфи. Свои стихи я подписывала псевдонимами Дилшод, Барно и Дилшоди Барно, а народ зовёт меня и Дилшод-отин.' WHERE id = 2156;
UPDATE fact_cards SET topic_ru = 'Моё учительство', question_ru = 'Каким делом занималась Дилшод-отин?', fact_ru = 'Грамоте я выучилась у отца. Потом я сама учительствовала и обучала грамоте женщин и девочек.' WHERE id = 2157;
UPDATE fact_cards SET topic_ru = 'Моя ученица Анбар Отин', question_ru = 'Кто была самой знаменитой ученицей Дилшод-отин?', fact_ru = 'В моей школе училось много девочек. Анбар Отин, ставшая позже знаменитой поэтессой, была одной из моих одарённых учениц.' WHERE id = 2158;
UPDATE fact_cards SET topic_ru = 'Моё поэтическое творчество', question_ru = 'На каких языках и в каких жанрах творила Дилшоди Барно?', fact_ru = 'Я творила на двух языках — узбекском и таджикском: слагала газели, мухаммасы, мусаддасы и чистаны. Моему перу принадлежат также «Тазкираи Барно» и «Мунтахаб аль-ашъори Барно».' WHERE id = 2159;
UPDATE fact_cards SET topic_ru = 'Мой труд «Тарихи муходжирон»', question_ru = 'Что освещено в труде Дилшоди Барно «Тарихи муходжирон»?', fact_ru = 'Я написала историко-литературный труд под названием «Тарихи муходжирон». В нём отражено виденное и узнанное мной в Кокандском ханстве — исторические и общественно-политические события.' WHERE id = 2160;
UPDATE fact_cards SET topic_ru = 'За просвещение женщин', question_ru = 'К чему призывала женщин Дилшоди Барно?', fact_ru = 'В своих произведениях я призывала женщин быть просвещёнными, свободными и равноправными членами общества. Ради этого я прежде всего сама обучала девочек грамоте.' WHERE id = 2161;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умерла Дилшоди Барно?', fact_ru = 'Я прожила долгую жизнь. Я скончалась в 1905 году в городе Коканде.' WHERE id = 2162;

-- ===== Komil Xorazmiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Комил Хорезми и каково его настоящее имя?', fact_ru = 'Я появился на свет в 1825 году в городе Хиве. Моё настоящее имя — Пахлаван Мухаммадниёз, сын Абдуллы Ахунда, а «Комил» — мой литературный псевдоним.' WHERE id = 1999;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'Где учился Комил Хорезми и какими языками он владел в совершенстве?', fact_ru = 'Я учился в хивинском медресе. В совершенстве изучил арабский и персидский языки.' WHERE id = 2000;
UPDATE fact_cards SET topic_ru = 'Моя служба при дворе', question_ru = 'В каких должностях служил Комил Хорезми при дворе хивинских ханов?', fact_ru = 'Я служил писцом при дворе хивинского хана Саида Мухаммадхана. Мухаммад Рахим II назначил меня мирзабаши, а в 1873–1880 годах я служил в должности диванбеги.' WHERE id = 2001;
UPDATE fact_cards SET topic_ru = 'Гандемианский договор', question_ru = 'Чьей рукой был написан Гандемианский мирный договор 1873 года?', fact_ru = 'Гандемианский мирный договор, заключённый в 1873 году между Россией и Хивинским ханством, был написан моей рукой.' WHERE id = 2002;
UPDATE fact_cards SET topic_ru = 'Нотация «танбурная линия»', question_ru = 'Какую систему записи нот ввёл Комил Хорезми для записи узбекских мелодий?', fact_ru = 'Для записи узбекских мелодий я ввёл систему нот, названную «танбурной линией», и записал этой нотацией главную часть макома «Раст». Позже мой сын Мирзо Мухаммадрасул положил на ноты остальные части хорезмских макомов.' WHERE id = 2003;
UPDATE fact_cards SET topic_ru = 'Мой диван и мои стихи', question_ru = 'Сколько стихотворных строк собрано в диване Комила Хорезми и какие темы в них воспеты?', fact_ru = 'В мой диван собрано более 8000 стихотворных строк в жанрах газели, касыды и других. В них я возвеличивал человеческие достоинства и осуждал невежество.' WHERE id = 2004;
UPDATE fact_cards SET topic_ru = 'Мои переводы и издания', question_ru = 'Какие произведения перевёл Комил Хорезми на узбекский язык и как он связан с первой типографией в Хорезме?', fact_ru = 'В 1865 году я перевёл с персидского на узбекский язык «Махбуб уль-кулуб», а в 1869–1870 годах — «Латоиф ат-тавоиф». В 1880–1881 годах я первым устроил в Хорезме типографию и написал предисловие к первому хорезмскому литографскому изданию «Хамсы» Алишера Навои.' WHERE id = 2005;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Комил Хорезми?', fact_ru = 'Я скончался в 1899 году. Вся моя жизнь была отдана служению развитию хивинской поэзии, каллиграфии и музыки.' WHERE id = 2006;

-- ===== Zavqiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Завки?', fact_ru = 'Я родился в 1853 году в городе Коканде. Моё полное имя — Убайдулла, сын Салиха, а «Завки» — мой литературный псевдоним.' WHERE id = 2020;
UPDATE fact_cards SET topic_ru = 'Моя учёба в медресе', question_ru = 'В каких медресе учился Завки?', fact_ru = 'В 1870–1874 годах я учился в кокандских медресе «Мадрасаи оли» и «Мадрасаи чалпак».' WHERE id = 2021;
UPDATE fact_cards SET topic_ru = 'Моё ремесло', question_ru = 'Каким ремеслом занимался Завки?', fact_ru = 'Я был ремесленником — шил махси. Некоторое время я служил и писцом.' WHERE id = 2022;
UPDATE fact_cards SET topic_ru = 'Мои поездки и паломничество', question_ru = 'С кем и куда совершил паломничество Завки в 1900 году?', fact_ru = 'Я побывал в городах Худжанд, Самарканд, Бухара, Ташкент, Ош, Андижан и Маргилан. В 1900 году вместе с моим дядей Мухаммадом Сиддиком я совершил паломничество в Медину, а в 1903 году вернулся в Коканд.' WHERE id = 2023;
UPDATE fact_cards SET topic_ru = 'Мои литературные друзья', question_ru = 'С какими поэтами творчески сотрудничал Завки?', fact_ru = 'В кокандской литературной среде я творчески сотрудничал с такими поэтами, как Мукими, Фуркат, Надим и Раджи. Я продолжал традиции классической узбекской литературы.' WHERE id = 2024;
UPDATE fact_cards SET topic_ru = 'Мои сатирические стихи', question_ru = 'Что разоблачал Завки в своих сатирических стихах?', fact_ru = 'Я написал такие сатирические стихи, как «Кривое время», «Дивное время», «Абдурахман-шайтан». В них я разоблачал общественное неравенство и несправедливость колониального порядка и проделки нечистых на руку чиновников.' WHERE id = 2025;
UPDATE fact_cards SET topic_ru = 'Мои произведения о народном горе', question_ru = 'В каких произведениях Завки отражены выступления народа против гнёта?', fact_ru = 'Я написал произведения «Случай с выборами казия» (1909–1910) и «Голод» (1916). В них я разоблачал общественную несправедливость и отразил выступления народа против гнёта.' WHERE id = 2026;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Завки?', fact_ru = 'Я скончался в 1921 году в родном городе Коканде. Мои стихи дошли до следующих поколений через разные баязы, сборники, периодическую печать и устные источники.' WHERE id = 2027;

-- ===== Avaz O'tar =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Аваз Утар?', fact_ru = 'Я родился 15 августа 1884 года в древнем городе Хиве. Мой отец Палваннияз был известен в народе под именем Утар, потому меня и зовут Аваз, сын Утара.' WHERE id = 2028;
UPDATE fact_cards SET topic_ru = 'Мой путь к знанию', question_ru = 'В каком медресе учился Аваз Утар и в каком возрасте он стал известен как поэт?', fact_ru = 'Сперва я учился в школе, затем в хивинском медресе Инакия. Уже в 18 лет я стал известен в народе как поэт.' WHERE id = 2029;
UPDATE fact_cards SET topic_ru = 'При дворе Феруза', question_ru = 'Какой хан пригласил Аваза Утара ко двору и назначил ему в наставники Табибия?', fact_ru = 'Хивинский хан Мухаммад Рахим Второй — Феруз — обратил внимание на моё дарование, пригласил меня ко двору и назначил мне в наставники Табибия. Но я не ужился с придворной жизнью и покинул двор.' WHERE id = 2030;
UPDATE fact_cards SET topic_ru = 'Мои диваны', question_ru = 'Какие два дивана Аваза Утара дошли до нас?', fact_ru = 'Мои стихи собраны в диваны «Саодат уль-икбол» и «Девони Аваз». Я написал множество произведений в жанрах газели, кыта и рубаи.' WHERE id = 2031;
UPDATE fact_cards SET topic_ru = 'Свобода и просвещение', question_ru = 'Какие мысли проводил Аваз Утар в своих стихах?', fact_ru = 'В начале XX века в своих стихах я воспевал свободолюбие, волю и просвещение. В таких стихах, как «Нация», «Свобода», «Народ», «Время», я говорил о боли моего народа.' WHERE id = 2032;
UPDATE fact_cards SET topic_ru = 'Моё стихотворение «Школа»', question_ru = 'О чём мечтал Аваз Утар в стихотворении «Школа»?', fact_ru = 'Я мечтал о том, чтобы молодёжь училась и получала знания. В стихотворении «Школа» я написал, что школа сделает нацию цветущей, а наша молодёжь, выучившись, обретёт радость в сердце.' WHERE id = 2033;
UPDATE fact_cards SET topic_ru = 'Сатира и журналы', question_ru = 'Как назывался цикл сатирических стихов Аваза Утара?', fact_ru = 'Смеясь над пороками своего времени, я писал сатирические стихи в цикле «Некто». Некоторые мои стихи печатались в журналах «Ойна», «Вакт» и «Мулла Насриддин».' WHERE id = 2034;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Аваз Утар?', fact_ru = 'Я скончался в 1919 году в родном городе Хиве. Хоть я и прожил короткую жизнь, я оставил своему народу стихи о свободе и просвещении.' WHERE id = 2035;

-- ===== Tavallo =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Тавалло?', fact_ru = 'Я родился в 1883 году в махалле Оби Назир Кукчинской даха Ташкента. Моё настоящее имя — Тулаган Ходжамьяров, а «Тавалло» — мой поэтический псевдоним.' WHERE id = 2338;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'Где учился Тавалло?', fact_ru = 'В детстве я выучился грамоте в старой школе. Затем я учился в ташкентском медресе Бекларбеги и в русско-туземной школе.' WHERE id = 2339;
UPDATE fact_cards SET topic_ru = 'Моя книга «Равнак уль-ислам»', question_ru = 'Какая книга Тавалло была издана?', fact_ru = 'В 1916 году я издал свой поэтический сборник «Равнак уль-ислам». В него вошло около 70 моих стихотворений, написанных размером аруз, — о жизни народа и о развитии нации. Это единственная моя книга, вышедшая при жизни.' WHERE id = 2340;
UPDATE fact_cards SET topic_ru = 'Мои стихи и печать', question_ru = 'Как выходили стихи Тавалло в печати?', fact_ru = 'Мои стихи и статьи с 1910-х годов начали печататься в периодике под псевдонимом «Тавалло». Не остались вне моего внимания и выход журнала «Ойна», и газеты «Садои Туркистон». Я написал такие стихи, как «О любимой Родине», «Обращение к перу».' WHERE id = 2341;
UPDATE fact_cards SET topic_ru = 'Товарищество «Нашриёт»', question_ru = 'В создании какого товарищества участвовал Тавалло?', fact_ru = '30 августа 1914 года вместе с друзьями — Мунавваркари и Авлони — я учредил товарищество «Нашриёт». Нашей целью было издавать книги для нашего народа.' WHERE id = 2342;
UPDATE fact_cards SET topic_ru = 'Театр и «Турон»', question_ru = 'Какова была связь Тавалло с театром?', fact_ru = '27 февраля 1914 года, когда труппа Авлони поставила в ташкентском театре «Колизей» драму Бехбуди «Отцеубийца», я посвятил этому событию стихотворение. А с 1915 года я действовал в обществе «Турон», созданном по почину Авлони и его товарищей.' WHERE id = 2343;
UPDATE fact_cards SET topic_ru = 'Мои сатирические стихи', question_ru = 'Писал ли Тавалло сатирические стихи?', fact_ru = 'Писал я и смешные, то есть сатирические стихи. В журнале «Муштум» десятки моих сатирических стихов печатались за подписью «Магзава».' WHERE id = 2344;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Чем завершилась жизнь Тавалло?', fact_ru = 'Я скончался в 1937 году. В том году, 14 августа, меня несправедливо взяли под стражу и обвинили в том, что в стихах я проводил националистические идеи. 10 ноября 1937 года я стал жертвой репрессий.' WHERE id = 2345;

-- ===== Elbek =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Эльбек?', fact_ru = 'Я родился в 1898 году в селении Хумсан Искандерской волости Ташкентской области, в семье бедного дехканина. Моё настоящее имя — Машрик Юнусов, Эльбек — мой литературный псевдоним. Моё детство и юность прошли очень тяжело.' WHERE id = 2170;
UPDATE fact_cards SET topic_ru = 'Мои школьные годы', question_ru = 'Где учился Эльбек и кем он работал?', fact_ru = 'В 1905 году я поступил в старую школу в нашем селении и, проучившись 4 года, выучился грамоте. В 1911 году я впервые приехал в Ташкент и учился в школе «Хани» в махалле Диванбеги Старого города. В 1914 году я перешёл в школу «Намуна», а позже и сам стал учительствовать.' WHERE id = 2171;
UPDATE fact_cards SET topic_ru = 'Мои поэтические сборники', question_ru = 'Какие поэтические сборники и произведения написал Эльбек?', fact_ru = 'Мой первый поэтический сборник «Армуган» напечатан в 1921 году. Затем я написал сборники «Зеркало», «Пламя» (1925) и «Весна» (1929). Изданы также мои рассказы «Ойхан» (1920) и «Пахарь Тургун» (1925) — о тяжком положении узбекских дехкан.' WHERE id = 2172;
UPDATE fact_cards SET topic_ru = 'Мои учебники', question_ru = 'Какие учебники для школ написал Эльбек?', fact_ru = 'Для детей я написал учебные книги «Образец» (1924), «Красивые прописи» (1925) и «Знание» (1927). Школам послужили и моё пособие «Родной язык в начальной школе», и книга «Словарь и термины» (1924).' WHERE id = 2173;
UPDATE fact_cards SET topic_ru = 'Моя борьба за родной язык', question_ru = 'Какой вклад внёс Эльбек в языкознание?', fact_ru = 'Изучая богатство и законы нашего родного языка, я написал такие статьи и пособия, как «Накануне созыва курултая по правописанию и языку» (1920), «О законах тюркских языков» (1922), «Учебник языка» (1923). В 1919 году я участвовал в «Чагатайской беседе» под началом Фитрата, а в узбекской научной комиссии работал вместе с Шакирджаном Рахими и Гази Юнусом.' WHERE id = 2174;
UPDATE fact_cards SET topic_ru = 'Народное устное творчество', question_ru = 'Как Эльбек собирал народное устное творчество?', fact_ru = 'Я очень любил песни нашего народа: вместе с Чулпаном и Гуламом Зафари я собрал в Фергане тысячи народных пословиц и поговорок, песен и лапаров. Я подготовил сборники «Лапары» (1924), «Сборник песен» и «Детские песни» (1934, 1935) для детей, а также приступил к составлению «Словаря узбекского фольклора».' WHERE id = 2175;
UPDATE fact_cards SET topic_ru = 'Мои переводы', question_ru = 'Какие произведения перевёл Эльбек на узбекский язык?', fact_ru = 'В 1937 году я перевёл на узбекский «Сказку о рыбаке и рыбке» и «Сказку о попе и о работнике его Балде» русского поэта Пушкина. Я переложил на родной язык и басни Крылова, и стихи Некрасова.' WHERE id = 2176;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Чем завершилась судьба Эльбека?', fact_ru = 'В годы культа личности Сталина меня несправедливо обвинили. Как и мои современники Фитрат, Чулпан, Абдулла Кадыри, я погиб безвинной жертвой. Точный год и место моей смерти неизвестны.' WHERE id = 2177;

-- ===== Hamid Olimjon =====
UPDATE fact_cards SET topic_ru = 'Моё рождение и детство', question_ru = 'Когда и где родился Хамид Алимджан?', fact_ru = 'Я родился 12 декабря 1909 года в городе Джизаке. Начальное образование я получил в школе имени Нариманова.' WHERE id = 2036;
UPDATE fact_cards SET topic_ru = 'Годы моей учёбы', question_ru = 'Где учился Хамид Алимджан?', fact_ru = 'В 1923–1926 годах я учился в Самаркандском педагогическом училище. Затем, в 1926–1931 годах, учился в Педакадемии.' WHERE id = 2037;
UPDATE fact_cards SET topic_ru = 'Мои поэтические сборники', question_ru = 'Как называется первый поэтический сборник Хамида Алимджана и когда он вышел?', fact_ru = 'Мои первые стихи начали выходить с 1926 года в газете «Зарафшан», а с 1927 года я работал в этой газете. В 1929 году был издан мой первый поэтический сборник «Весна». Затем я написал сборники «Ночь реки» (1936), «Край» (1939) и «Счастье» (1940).' WHERE id = 2038;
UPDATE fact_cards SET topic_ru = 'Дастан «Зайнаб и Аман»', question_ru = 'Какой из дастанов Хамида Алимджана самый знаменитый?', fact_ru = 'Одно из самых знаменитых моих произведений — дастан «Зайнаб и Аман», я написал его в 1930-е годы. Есть у меня и дастан «Повесть о двух девушках» (1935–1937).' WHERE id = 2039;
UPDATE fact_cards SET topic_ru = 'Мои другие дастаны и баллады', question_ru = 'В каком жанре написаны произведения Хамида Алимджана «Ойгуль и Бахтияр» и «Семург»?', fact_ru = 'Я написал дастаны «Ойгуль и Бахтияр» (1937) и «Семург» (1939). Создал я и такие баллады, как «Боец Турсун» и «Слёзы Роксаны».' WHERE id = 2040;
UPDATE fact_cards SET topic_ru = 'Мои драмы и переводы', question_ru = 'Какую стихотворную драму написал Хамид Алимджан и чьи произведения он переводил?', fact_ru = 'Я написал стихотворную драму «Муканна» и драму «Преступление». Я переводил на узбекский язык произведения Пушкина, Толстого, Горького, Маяковского и Лермонтова.' WHERE id = 2041;
UPDATE fact_cards SET topic_ru = 'Моя руководящая работа', question_ru = 'Какой организацией руководил Хамид Алимджан?', fact_ru = 'С 1939 года и до конца жизни я руководил Союзом писателей Узбекистана. В 1943 году я был избран членом-корреспондентом Академии наук Узбекистана.' WHERE id = 2042;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и как погиб Хамид Алимджан?', fact_ru = 'Я погиб 3 июля 1944 года в автомобильной катастрофе. Мне было всего 34 года.' WHERE id = 2043;

-- ===== Usmon Nosir =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Усман Насыр?', fact_ru = 'Я родился 13 ноября 1912 года в Наманганской области.' WHERE id = 2044;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'Где учился Усман Насыр?', fact_ru = 'В 1929–1930 годах я учился на сценарном факультете Института кинематографии в Москве, а в 1933–1934 годах — на факультете языка и литературы Самаркандского государственного университета имени Алишера Навои.' WHERE id = 2045;
UPDATE fact_cards SET topic_ru = 'Моё стихотворение «Сердце»', question_ru = 'Какими строками начинается стихотворение Усмана Насыра «Сердце»?', fact_ru = 'Одно из самых знаменитых моих стихотворений — «Сердце». Оно начинается так: «Сердце, ты мой саз, / Ты язык мой заставило вторить нею». В 1935 году был издан и мой поэтический сборник «Сердце».' WHERE id = 2046;
UPDATE fact_cards SET topic_ru = 'Мои поэтические сборники', question_ru = 'Какие поэтические сборники и дастаны написал Усман Насыр?', fact_ru = 'Я написал поэтические сборники «Беседа с солнцем», «Мобилизованные строки» (1932), «Тракторобад» (1934), «Сердце» (1935) и «Моя любовь» (1936). В 1934 году я создал также дастаны «Норбута» и «Нахшон».' WHERE id = 2047;
UPDATE fact_cards SET topic_ru = 'Моя драма «Атлас»', question_ru = 'Что известно о драме Усмана Насыра «Атлас»?', fact_ru = 'В 1935 году я написал стихотворную драму под названием «Атлас». Это моё произведение было поставлено на сцене любительского театра.' WHERE id = 2048;
UPDATE fact_cards SET topic_ru = 'Мои переводы', question_ru = 'Какие произведения перевёл Усман Насыр на узбекский язык?', fact_ru = 'Я перекладывал на узбекский язык произведения русских поэтов: я перевёл поэмы «Бахчисарайский фонтан» Пушкина и «Демон» Лермонтова.' WHERE id = 2049;
UPDATE fact_cards SET topic_ru = 'Жертва репрессий', question_ru = 'За что и когда был арестован Усман Насыр?', fact_ru = '13 июля 1937 года меня взяли под стражу по обвинению во «враждебности народу». Меня отправили сначала в магаданские, затем в кемеровские лагеря.' WHERE id = 2050;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Усман Насыр?', fact_ru = 'Я скончался 9 марта 1944 года в заключении в Кемеровской области.' WHERE id = 2051;
